def is_gp(seq):
    """Check if a sequence is a geometric progression."""
    n = len(seq)
    if n <= 1:
        return True

    # If all elements are 0
    if all(x == 0 for x in seq):
        return True

    # If first element is 0
    if seq[0] == 0:
        # All remaining elements must also be 0
        return all(x == 0 for i in range(1, n))

    # Check common ratio: if all elements are the same
    if all(x == seq[0] for x in seq):
        return True

    # For non-trivial GP, check if seq[i] * seq[0] == seq[i-1] * seq[1] for all i
    # This avoids floating point division
    base = seq[0]
    ratio_num = seq[1]

    for i in range(2, n):
        if seq[i] * base != seq[i-1] * ratio_num:
            return False

    return True


