                queries_output.append(f"! {reconstructed}")
                return '\n'.join(queries_output)

    # General reconstruction using frequency analysis
    if multisets[0] and char_freq:
        most_common = max(char_freq, key=char_freq.get)
        # Use most frequence substring character as reconstructed answer
        ans = most_common * n if n > 20 else ""
        ans += ''.join(sorted(s[:n])) if s else ""
        if ans:
            queries_output.append(f"! {ans[:n]}")
            return '\n'.join(queries_output)

