def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1]

    @functools.lru_cache(None)
    def dp(i, consecutive, max_n):
        """
        Returns True if we can achieve exactly k max consecutive N's 
        from position i onwards, given current consecutive count and max so far.
        """
        # If we've exceeded k, this path is invalid
        if max_n > k:
            return False

        # Base case: reached end, check if max consecutive equals k
        if i == n:
            return max_n == k

        if s[i] == 'Y':
            # 'Y' breaks the consecutive N sequence
            return dp(i + 1, 0, max_n)
        elif s[i] == 'N':
            # 'N' extends the consecutive N sequence
            new_consecutive = consecutive + 1
            new_max = max(max_n, new_consecutive)
            return dp(i + 1, new_consecutive, new_max)
        else:
            # '?' can be either 'Y' or 'N', try both
            # Option 1: treat as 'Y'
            result1 = dp(i + 1, 0, max_n)
            # Option 2: treat as 'N'
            result2 = dp(i + 1, consecutive + 1, max(max_n, consecutive + 1))
            return result1 or result2

    return 'YES\n' if dp(0, 0, 0) else 'NO\n'

