def f_lazy_simulation(x, y):
    count = 0
    while y > 0:
        g = gcd(x, y)
        step_size = g
        if step_size == 0:
            break
        # How many times can we subtract step_size before gcd changes?
        if y % step_size == 0:
            # We can reach y - k*g = 0 directly
            count += y // step_size
            y = 0
            continue

        # Find the threshold where gcd changes
        # We need to find the largest k such that gcd(x, y - k*g) stays the same
        # gcd(x, y) == g
        # The next GCD changes when y - k*g reaches a multiple of some divisor

        # Simpler approach: when y % g != 0, let's not simulate step by step
        # Instead, calculate how many steps until y becomes a multiple of some smaller gcd

        # For this, we observe that if gcd(x, y) = g, then gcd(x, y/k) = g/k when k divides both
        # When not divisible, we need more sophisticated handling

        # Heuristic: When y is large and gcd is small, we can simulate or use patterns
        if y <= 2 * x:
            # Simulate step by step when y is relatively small compared to x
            while y % g == 0 and y > 0:
                count += y // g
                y = 0
            break
        else:
            # When y is much larger, simulate step by step until significant change
            # or y becomes small enough
            if y % g == 0:
                count += y // g
                y = 0
            else:
                # Force the sequence faster by using patterns
                count += 1
                y -= g

    return count

