def solution(input_str):
    """
    Solves the microwave banana problem.

    For each time step, we can apply an operation up to y_i times.
    We track all reachable banana counts and find the earliest time
    each target (1 to m) can be achieved.

    Args:
        input_str: Input string containing test case data

    Returns:
        String with m space-separated integers (earliest time for each banana count)
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse operations
    operations = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t_i = int(parts[0])
        x_prime_i = int(parts[1])
        y_i = int(parts[2])
        # x_i = x'_i / 100000 (given in problem)
        x_i = x_prime_i / 100000.0
        operations.append((t_i, x_i, y_i))

    # first_reach[j] = earliest time we can achieve exactly j bananas
    # Initialize with -1 (unreachable)
    first_reach = [-1] * m

    # Track all reachable banana counts as we process each time step
    current_reachable = {0}

    for i in range(1, n + 1):
        t_i, x_i, y_i = operations[i-1]
        new_counts_from_i = set()

        # For each count achievable at time i-1, try all possible applications
        # of operation i (0 to y_i times)
        for c in current_reachable:
            if c >= m:  # Handle overflow (though c < m per loop)
                continue

            # Try applying operation i, a times where a ∈ [0, y_i]
            for a in range(y_i + 1):
                curr = c

                if t_i == 1:
                    # Type 1: k := ceil(k + x_i) applied a times
                    # ceil(k + x_i) = k + ceil(x_i) since adding non-integer works the same as adding ceil
                    ceil_x = math.ceil(x_i)
                    curr = c + a * ceil_x
                else:
                    # Type 2: k := ceil(k * x_i) applied a times
                    # Each application with ceil is computed independently
                    temp = c
                    for _ in range(a):
                        temp = math.ceil(temp * x_i)
                    curr = temp

                # Only keep counts within valid range [0, m-1]
                if curr < m and curr >= 0:
                    new_counts_from_i.add(curr)

        # Update reachable set with newly discovered counts
        current_reachable.update(new_counts_from_i)

        # Record first reach time for counts discovered at this time step
        for c in new_counts_from_i:
            if c > 0 and c < m and first_reach[c - 1] == -1:
                first_reach[c - 1] = i

    # Format output: space-separated integers for banana counts 1 to m
    return ' '.join(map(str, first_reach)) + '\n'


