def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0"

    n, m, k, p = map(int, lines[0].split())
    bamboos = []
    for i in range(n):
        parts = lines[i+1].split()
        if len(parts) >= 2:
            hi, ai = int(parts[0]), int(parts[1])
            bamboos.append((hi, ai))

    # Handle edge case of no bamboos
    if not bamboos:
        return "0"

    # Binary search to find the minimum achievable maximum height
    low = 0
    # Maximum possible height without any hammer use (发生在所有bamboo都不被打的时候)
    high = max(hi + m * ai for hi, ai in bamboos)

    def can_achieve(target):
        """Check if it's possible to achieve max height <= target"""
        if p == 0:
            # If p=0, hammering doesn't reduce height, so impossible unless already satisfied
            return all(hi + m * ai <= target for hi, ai in bamboos)

        required_hits = 0
        for hi, ai in bamboos:
            final_without_hits = hi + m * ai
            if final_without_hits > target:
                needed = final_without_hits - target
                # Calculate ceil(needed / p)
                hits_needed = (needed + p - 1) // p
                required_hits += hits_needed

        # Total hammer hits available = k * m days * k hits per day
        return required_hits <= k * m

    # Binary search
    while low < high:
        mid = (low + high) // 2
        if can_achieve(mid):
            high = mid
        else:
            low = mid + 1

    return str(low)

