def solution(input_str):
    lines = input_str.strip().split('\n')
    n, q = int(lines[0].split()[0]), int(lines[0].split()[1])

    vertices = []
    for i in range(1, n+1):
        x, y = map(int, lines[i].split())
        vertices.append((x, y))

    queries = []
    for i in range(n+1, n+q+1):
        queries.append(int(lines[i]))

    def shoelace_area(pts):
        """Calculate area of polygon using shoelace formula"""
        area = 0
        for i in range(len(pts)):
            p1 = pts[i]
            p2 = pts[(i+1) % len(pts)]
            area += p1[0] * p2[1] - p2[0] * p1[1]
        return abs(area) / 2

    def clip_at(f):
        """Clip polygon at x = f, keeping right side (x >= f)"""
        clipped = []

        m = len(vertices)
        prev_p = vertices[m-1]
        prev_in = prev_p[0] >= f

        for i in range(m):
            curr_p = vertices[i]
            curr_in = curr_p[0] >= f

            # Edge crosses from outside to inside (or at boundary)
            if prev_in == False and curr_in == True:
                # Edge goes from left to right
                if curr_p[0] != prev_p[0]:
                    t = (f - prev_p[0]) / (curr_p[0] - prev_p[0])
                    intersect_y = prev_p[1] + t * (curr_p[1] - prev_p[1])
                    clipped.append((f, intersect_y))
            # Edge crosses from inside to outside (compute intersection)
            elif prev_in == True and curr_in == False:
                if curr_p[0] != prev_p[0]:
                    t = (f - prev_p[0]) / (curr_p[0] - prev_p[0])
                    intersect_y = prev_p[1] + t * (curr_p[1] - prev_p[1])
                    clipped.append((f, intersect_y))

            # If both vertices are inside or after adding intersection, add current vertex
            if prev_in:
                if i == m - 1 or curr_p[0] >= f:
                    clipped.append(curr_p)

        return shoelace_area(clipped)

    results = []
    for f in queries:
        results.append(f"{clip_at(f):.10f}")

    return '\n'.join(results)


