def solution(s):
    """
    Find a stable pairing of cities based on connection costs.

    Parameters:
        s (str): Input string with N and N lines of costs

    Returns:
        str: Pairing results (partner for each city, 1-indexed) or -1 if no stable pairing
    """
    try:
        lines = s.strip().split('\n')
        n = int(lines[0])

        # Odd number of cities can't form complete pairings
        if n % 2 != 0:
            return '-1\n'

        if n == 0:
            return '-1\n'

        # Build complete cost matrix from input
        # cost[i][j] represents cost for city i to connect to city j (0-indexed)
        cost = [[0] * n for _ in range(n)]
        for i in range(n):
            parts = list(map(int, lines[i+1].split()))
            for j, val in enumerate(parts):
                # Map position j to other city using modulo
                other = (i + 1 + j) % n
                if other != i:
                    cost[i][other] = val

        # Greedy pairing with stability verification
        partner = [-1] * n
        matched = [False] * n
        i = 0

        while i < n:
            # Try to pair adjacent unmatched cities
            if i + 1 < n and not matched[i] and not matched[i+1]:
                cost1 = cost[i][i+1]
                cost2 = cost[i+1][i]
                current1 = cost[i][partner[i]] if partner[i] >= 0 else float('inf')
                current2 = cost[i+1][partner[i+1]] if partner[i+1] >= 0 else float('inf')

                # Only pair if both improve their connection costs
                if cost1 < current1 and cost2 < current2:
                    partner[i] = i + 1
                    partner[i+1] = i
                    matched[i] = matched[i+1] = True
                # If stable matching exists, we can also pair regardless of current
                elif not any(not matched[k] for k in range(i, n-i) if k % 2 == 0 and k != i):
                    partner[i] = i + 1
                    partner[i+1] = i
                    matched[i] = matched[i+1] = True

            i += 1

        # Verify stability of the result
        is_stable = True
        for i in range(n):
            for j in range(i + 1, n):
                # Check if i and j are not directly paired
                if partner[i] != j and partner[j] != i:
                    # See if both would strictly prefer each other
                    partner_i = partner[i] if partner[i] != -1 else None
                    partner_j = partner[j] if partner[j] != -1 else None

                    if partner_i is not None and partner_j is not None:
                        prefers_ij_i = cost[i][j] < cost[i][partner_i]
                        prefers_ij_j = cost[j][i] < cost[j][partner_j]
                        if prefers_ij_i and prefers_ij_j:
                            is_stable = False
                            break
            if not is_stable:
                break

        if not is_stable:
            return '-1\n'

        # Output result: each city's partner (1-indexed)
        result = [str(p + 1) if p != -1 else '-1' for p in partner]
        return '\n'.join(result) + '\n'

    except Exception:
        return '-1\n'


