def mat_mul(A, B):
    C = [[0, 0, 0] for _ in range(3)]
    for i in range(3):
        for j in range(3):
            for k in range(3):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(A, p):
    if p == 0:
        return [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    result = [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    base = A
    while p:
        if p & 1:
            result = mat_mul(result, base)
        base = mat_mul(base, base)
        p >>= 1
    return result

