def solution(input_data):
    """
    Andrew and Eugene are playing a game. Eugene sends Andrew multiple queries 
    that replace digits in a string. After all queries, return the number 
    modulo 10^9 + 7.

    Args:
        input_data: Multiline string containing:
            - original string s
            - number of queries n
            - n lines of queries (format: "d->t")

    Returns:
        Integer result modulo 1000000007
    """
    # Parse input
    lines = input_data.strip().split('\n')
    if not lines:
        return "0"

    s = lines[0]
    if not s:
        return "0"

    # Parse n (may be on separate line or cleaned)
    n_line = 1
    while n_line < len(lines) and lines[n_line].strip() == '':
        n_line += 1
    if n_line >= len(lines):
        return "0"

    try:
        n = int(lines[n_line])
    except:
        n = 0

    queries = []
    i = n_line + 1
    while i < len(lines):
        query = lines[i].strip()
        if query:
            queries.append(query)
        i += 1

    MOD = 1000000007

    # mapping[d] = string that digit 'd' ultimately transforms into
    # Process queries in order (1 to n)
    # For d -> t: digit d replaces with t, then t's digits transform according to current mapping
    mapping = {str(i): str(i) for i in range(10)}

    for query in queries:
        try:
            # Parse "d->t"
            arrow_idx = query.find('->')
            if arrow_idx == -1:
                continue
            d = query[:arrow_idx].strip()
            t = query[arrow_idx+2:].strip()

            if d not in mapping or not d.isdigit():
                continue

            # For each character in t, get its current transformation
            final_t = []
            for char in t:
                if char in mapping:
                    final_t.append(mapping[char])
                else:
                    # Character not yet transformed, keep as is
                    final_t.append(str(char))

            mapping[d] = ''.join(final_t)
        except:
            continue

    # Now apply transformations to the original string s
    # Compute the final number modulo MOD without materializing the huge string

    result = 0
    for digit in s:
        if digit not in mapping:
            # Digit has no transformation
            digit_char = digit
        else:
            digit_char = mapping[digit]

        for char in digit_char:
            if ord('0') <= ord(char) <= ord('9'):
                digit_val = int(char)
                result = (result * 10 + digit_val) % MOD

    return str(result)

