            pair_data[i] = (a, b)
        elif t == 2:  # Remove pair from query i
            query_idx = int(parts[1])
            if query_idx in active_pairs:
                active_pairs.remove(query_idx)
                del pair_data[query_idx]
        elif t == 3:  # Query: find max(a*q + b)
            q = int(parts[1])
            if not active_pairs:
                results.append("EMPTY SET")
            else:
                max_val = None
                for query_idx in active_pairs:
                    a, b = pair_data[query_idx]
                    val = a * q + b
                    if max_val is None or val > max_val:
                        max_val = val
                results.append(str(max_val))

    return '\n'.join(results)

