def solution(s):
    a, b, n = map(int, s.strip().split())

    if a == 1:
        # When a=1, 1^b = 1 for all b, which is always < n
        # Player can always increase b to stay in the game forever
        # This creates a draw
        return Passer()

    # Memoization for game states
    memo = {}

    def can_win(a, b, n):
        """Returns True if current player wins from state (a, b), else False or Draw"""
        if (a, b) in memo:
            return memo[(a, b)]

        # Current player loses if a^b >= n (shouldn't happen at valid starting states)
        if a ** b >= n:
            return False

        # Check if any move leads opponent to losing state
        can_forced_lose = False
        can_force_win = False

        # Try increasing boxes
        if (a + 1) ** b < n:
            if not can_win(a + 1, b, n):
                # Opponent loses from this state, so current player wins
                can_forced_lose = True

        # Try increasing items  
        if a ** (b + 1) < n:
            if not can_win(a, b + 1, n):
                can_forced_lose = True

        if can_forced_lose:
            # Can force opponent into losing position
            memo[(a, b)] = True
            return True

        # All moves lead to states where opponent can win
