def solution(matrix_str):
    lines = matrix_str.strip().split('\n')
    n = int(lines[0])
    matrix = [list(map(int, line.split())) for line in lines[1:n+1]]

    # Precompute factors for each cell
    factors = [[(0, 0)] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            val = matrix[i][j]
            if val > 0:
                temp = val
                c2 = 0
                while temp % 2 == 0:
                    c2 += 1
                    temp //= 2
                temp = val
                c5 = 0
                while temp % 5 == 0:
                    c5 += 1
                    temp //= 5
                factors[i][j] = (c2, c5)
            else:
                factors[i][j] = (0, 0)

    # dp[i][j] = list of (cnt2, cnt5, path) tuples
    dp = [[[] for _ in range(n)] for _ in range(n)]

    # Start at top-left
    dp[0][0].append((factors[0][0][0], factors[0][0][1], ""))

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            c2, c5 = factors[i][j]
            opts = []

            # From above
            if i > 0:
                for st in dp[i - 1][j]:
                    opts.append((st[0] + c2, st[1] + c5, st[2] + 'D'))

            # From left
            if j > 0:
                for st in dp[i][j - 1]:
                    opts.append((st[0] + c2, st[1] + c5, st[2] + 'R'))

            if opts:
                dp[i][j] = opts

                # Remove dominated states (Pareto pruning)
                keep = []
                for st in opts:
                    is_dominated = False
                    for st2 in opts:
                        if st != st2 and st[0] >= st2[0] and st[1] >= st2[1]:
                            is_dominated = True
                            break
                    if not is_dominated:
                        keep.append(st)
                dp[i][j] = keep

    # Find best result at bottom-right corner
    found = False
    min_zeros = 0
    ans_path = ""
    for st in dp[n - 1][n - 1]:
        zeros = min(st[0], st[1])
        if not found or zeros < min_zeros:
            min_zeros = zeros
            ans_path = st[2]
            found = True

    return f"{min_zeros}\n{ans_path}" if found else "0\n"

