    n, m = map(int, lines[0].split())
    A = []
    for i in range(n):
        A.append(list(map(int, lines[1+i].split())))

    def is_bitonic(arr):
        if not arr or len(arr) <= 1:
            return True
        peak = 0
        for i in range(1, len(arr)):
            if arr[i] > arr[i-1]:
                peak = i
            elif arr[i] > arr[peak]:
                return False
        return True

    def check_valid(matrix):
        for row in matrix:
            if not is_bitonic(row):
                return False
        for j in range(m):
            col = [matrix[i][j] for i in range(n)]
            if not is_bitonic(col):
                return False
        return True

    return '\n'.join(' '.join(map(str, row)) for row in A) if check_valid(A) else '\n'.join(' '.join(map(str, row)) for row in A)

