import os

MOD = 1051131

def multiply(A, B, n):
    """Matrix multiplication mod MOD"""
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            for j in range(n):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(A, t, n):
    """Matrix exponentiation mod MOD"""
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = [row[:] for row in A]
    while t > 0:
        if t % 2 == 1:
            result = multiply(result, base, n)
        base = multiply(base, base, n)
        t //= 2
    return result

def multiply_vec_mat(vec, T, n):
    """Vector-matrix multiplication mod MOD"""
    result = [0] * n
    for i in range(n):
        for j in range(n):
            result[i] = (result[i] + vec[j] * T[j][i]) % MOD
    return result

