    if n >= 3:
        slope1 = None
        for i in range(1, n):
            x1, y1 = circles[0], circles[i]
            x2, y2 = circles[i], circles[i+1] if i+1 < n else circles[0]

            if slope1 is None:
                if abs(x1 - x2) > 1e-9:
                    slope1 = (y2 - y1) / (x2 - x1)
                else:
                    slope1 = float('inf')

            curr_slope = float('inf')
            if abs(x1 - x2) > 1e-9:
                curr_slope = (y2 - y1) / (x2 - x1)

            if abs(slope1 - curr_slope) > 1e-9 or (slope1 == float('inf') and curr_slope != float('inf')):
                is_collinear = False
                break

    # For collinear or small n, no holes can form
    if is_collinear or n < 3:
        return "-1"

    # Find all pairwise distances
    max_dist = 0
    for i in range(n):
        for j in range(i + 1, n):
            d = dist(circles[i], circles[j])
            max_dist = max(max_dist, d)

    if max_dist < 1e-9:
        return "-1"

    # The answer is max_dist / 2
    return "{:.6f}".format(max_dist / 2)

