    def get_prime_factors(num):
        factors = set()
        d = 2
        temp = num
        while d * d <= temp:
            while temp % d == 0:
                factors.add(d)
                temp //= d
            d += 1
        if temp > 1:
            factors.add(temp)
        return list(factors)

    candidates = set()
    for i in [0, min(5, n-1), n-1]:
