        candidates.update(get_prime_factors(arr[i] - 1))
        candidates.update(get_prime_factors(arr[i] + 1))

    ans = float('inf')

    for p in candidates:
        change_cost = 0
        for x in arr:
            if x % p == 0:
                continue
            elif (x % p) == p - 1 or abs(x % p - 1) == 0:
                change_cost += 1
            else:
                continue

        if change_cost <= n:
            cost = change_cost * b
            ans = min(ans, cost)

    return str(ans) if ans != float('inf') else '0'

