import sys
from functools import lru_cache

sys.setrecursionlimit(50000)

def solution(input_string):
    n, k, m = map(int, input_string.strip().split())
    MOD = 10**9 + 7

    @lru_cache(maxsize=None)
    def count_ways(last, visited, length):
        """Count valid ways to complete a path from 'last' position with 'length' steps remaining."""
        if length == 0:
            return 1

        res = 0
        reachable_limit = min(n, last + m)
        for nxt in range(1, reachable_limit + 1):
            if nxt not in visited:
                new_visited = visited | {nxt}
                res = (res + count_ways(nxt, new_visited, length - 1)) % MOD
        return res

    ans = 0
    for start in range(1, n + 1):
        ans = (ans + count_ways(start, frozenset({start}), k - 1)) % MOD

    return str(ans)

import itertools

def solution(input_string):
    input_string = input_string.strip()
    if not input_string:
        return "0"

    lines = input_string.split('\n')
    n, m = map(int, lines[0].split())
    attempts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        attempts.append((int(parts[0], 2), int(parts[1])))

    if m == 0:
        return str(1 << n)

    s0, c0 = attempts[0]
    cands = []

    # Generate codes that match s0 in exactly c0 positions
    for subset in itertools.combinations(range(n), c0):
        code = 0
        for i in range(n):
            if i in subset:
                code |= (1 << i)  # matching: code[i] == s0[i]
            else:
                code |= (1 << i)  # not matching: code[i] == not s0[i] (we're building the opposite)
        cands.append(code)

    count = 0
    for code in cands:
        valid = True
        for s, c in attempts:
            matches = 0
            for i in range(n):
                if ((code >> i) & 1) == ((s >> i) & 1):
                    matches += 1
            if matches != c:
                valid = False
                break
        if valid:
            count += 1

    return str(count)
